fn walk(s:&Path,v:&mut Vec<PathBuf>){for f in fs::read_dir(s).unwrap(){let f=f.unwrap().path();if f.is_dir(){walk(&f,v)}else{v.push(f)}}}
fn seal(){assert!(!p("capture-plan.json").exists());let mut pins=read(p("pins.json"));for f in["control-fixed.rs","control-fixed","control-fixed-build.log","repair.rs","repair","repair.log","publish.rs","publish","publish-build.log","native-fixed-plan.json","native-fixed-pins.json","native1.log","native-fixed.log","prepare.log"]{pins[format!("{R}/{f}")]=json!(hash(p(f)));}let mut files=Vec::new();walk(&p("initial-native1"),&mut files);for f in files{pins[f.display().to_string()]=json!(hash(&f));}save(p("capture-pins.json"),&pins);let mut plan=read(p("run-plan.json"));plan["source_pins"]=json!(p("capture-pins.json"));save(p("capture-plan.json"),&plan);println!("Sealed {} pins including original compile failure/import repair and publication helper",pins.as_object().unwrap().len());}
fn med(v:&mut[f64])->f64{v.sort_by(f64::total_cmp);v[v.len()/2]}
fn profiles()->(Value,bool){let mut all=BTreeMap::new();let mut qualified=true;for k in["norm","anchors"]{for a in["off","new"]{let name=format!("profile-{k}-{a}");let result=read(p("rows.json")).as_array().unwrap().iter().find(|r|r["job"]["name"]==name).unwrap()["result"].clone();let workers:BTreeMap<_,_>=result["workers"].as_array().unwrap().iter().map(|v|(v["tid"].as_i64().unwrap()as u64,v["cpu"].as_u64().unwrap())).collect();let mut pids=BTreeSet::new();let mut tids=BTreeSet::new();let(mut samples,mut total,mut unknown)=(0u64,0u64,0u64);let mut weights=BTreeMap::<String,u64>::new();let mut times=Vec::new();
 let decoded=fs::read_to_string(p(&format!("runs/decode-{k}-{a}/stdout.log"))).unwrap();for l in decoded.lines(){let t:Vec<_>=l.split_whitespace().collect();if t.is_empty()||t[0].starts_with('#'){continue}if !t[0].contains('/')||t.len()<7{continue}let(pid,tid)=t[0].split_once('/').unwrap();let(pid,tid)=(pid.parse::<u64>().unwrap(),tid.parse::<u64>().unwrap());let cpu=t[1].trim_matches(['[',']']).parse::<u64>().unwrap();let time=t[2].trim_end_matches(':').parse::<f64>().unwrap();let period=t.iter().skip(3).find_map(|v|v.parse::<u64>().ok()).unwrap();assert!(cpu<32);if let Some(&c)=workers.get(&tid){assert_eq!(cpu,c);}pids.insert(pid);tids.insert(tid);times.push(time);samples+=1;total+=period;
 let ip=t.iter().enumerate().skip(3).find(|(_,s)|s.len()>=12&&s.chars().all(|c|c.is_ascii_hexdigit())).map(|(i,_)|i).unwrap();let symbol=t[ip+1];if symbol=="[unknown]"{unknown+=period;}let dem=format!("{:#}",rustc_demangle::demangle(symbol));*weights.entry(dem).or_default()+=period;
 }
 let loss=fs::read_to_string(p(&format!("runs/lost-{k}-{a}/stdout.log"))).unwrap();let ev=fs::read_to_string(p(&format!("runs/events-{k}-{a}/stdout.log"))).unwrap();let lost=loss.lines().filter(|l|l.contains("PERF_RECORD_LOST")).count();let active=workers.keys().all(|t|tids.contains(t));let fixed=ev.contains("16000000")&&ev.contains("cycles:u");let q=samples>=1000&&pids.len()==1&&lost==0&&active&&fixed&&total>0&&unknown as f64/total as f64<=0.05;qualified&=q;times.sort_by(f64::total_cmp);
 all.insert(name,json!({"samples":samples,"period_sum":total,"unknown_period":unknown,"unknown_fraction":unknown as f64/total.max(1)as f64,"pids":pids,"sampled_tids":tids,"all_workers_sampled":active,"zero_lost_records":lost==0,"fixed_period":fixed,"first_time":times.first(),"last_time":times.last(),"qualified":q,"symbol_periods":weights,"data_sha256":hash(p(&format!("profile-{k}-{a}.data")))}));
 }}(json!(all),qualified)}
fn receipts()->Value{let mut count=0;for dir in["native0","native1","runs"]{let result=read(p(&format!("{dir}/result.json")));assert_eq!(result["status"],"complete");for s in result["steps"].as_array().unwrap(){let s=s.as_str().unwrap();let e=read(p(&format!("{dir}/{s}/exit.json")));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(p(&format!("{dir}/{s}/{stream}.log"))),e[format!("{stream}_sha256")].as_str().unwrap());}count+=1;}}let fail=read(p("initial-native1/runs/new-field-tests/exit.json"));assert_eq!(fail["returncode"],101);json!({"successful_commands":count,"initial_native_test_compile_exit":101,"successful_capture_or_test_repeats":0})}
fn archive(label:&str,files:&[PathBuf])->Value{let mut v=Vec::new();for f in files{let b=fs::read(f).unwrap();v.push(json!({"path":f.strip_prefix(R).unwrap().display().to_string(),"sha256":h(&b),"utf8":String::from_utf8(b).unwrap()}));}let bytes=serde_json::to_vec(&v).unwrap();let temp=p(&format!("{label}-archive.tmp.json"));fs::write(&temp,&bytes).unwrap();let to=Path::new(D).join(format!("artifacts/{label}.json.gz"));assert!(Command::new("gzip").args(["-n","-c"]).stdin(Stdio::from(fs::File::open(&temp).unwrap())).stdout(Stdio::from(fs::File::create(&to).unwrap())).status().unwrap().success());let out=Command::new("gzip").args(["-dc",to.to_str().unwrap()]).output().unwrap();assert!(out.status.success());assert_eq!(out.stdout,bytes);fs::remove_file(temp).unwrap();json!({"members":v.len(),"compressed_sha256":hash(&to),"exact_roundtrip":true})}
