 let mut inverse_count=0;for(f,x)in read(p("production-pins.json")).as_object().unwrap(){assert_eq!(hash(f),x.as_str().unwrap());if let Some(t)=f.strip_prefix(&format!("{Z}/crates/zopro-bn254/")){let mut b=fs::read(p(&format!("bn254/{t}"))).unwrap();if t=="src/ifma8.rs"{let suffix=b"\ninclude!(\"../../kernel.rs\");\n";assert!(b.ends_with(suffix));b.truncate(b.len()-suffix.len());}assert_eq!(h(&b),x.as_str().unwrap());inverse_count+=1;}}assert_eq!(inverse_count,17);
 let(profiles,q)=profiles();save(p("profiles.json"),&profiles);let rec=receipts();fs::create_dir_all(Path::new(D).join("artifacts")).unwrap();for f in["analysis.json","identities.json","profiles.json","design.md","bounds.md","pre-build-repairs.md","kernel.rs","repair.rs","production-pins.json","capture-plan.json","capture-pins.json","jobs.json"]{fs::copy(p(f),Path::new(D).join("artifacts").join(f)).unwrap();}
